/**
 * Dashboard.Panel: a named region: a Card with its heading.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dashboard.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import Card from '../structure/Card'

export interface DashboardPanelProps {
  /**
   * Rendered as an `h2` with the system's section-heading recipe.
   */
  title?: string
  children: JSX.Element
}

/** Dashboard.Panel: a named region: a Card with its heading. */
export default function DashboardPanel(given: DashboardPanelProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return <Card title={props.title}>{props.children}</Card>
  })
}
